import { createHash } from "node:crypto";

const REPRODUCER_KINDS = new Set(["scenario", "route", "command-id"]);
const FAILURE_STATUSES = new Set(["fail", "failed", "failure", "error", "errored"]);
const PASS_STATUSES = new Set(["pass", "passed", "success", "succeeded", "rejected", "cancelled", "canceled", "skipped"]);
const MAX_REPRODUCER_BYTES = 16 * 1024;
const MAX_STRING_LENGTH = 4 * 1024;
const MAX_DEPTH = 4;
const MAX_ARRAY_ITEMS = 100;
const MAX_OBJECT_KEYS = 50;
const RECENT_TRACE_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;

const FORBIDDEN_KEYS = new Map([
  ["rawprompt", "raw-prompt"],
  ["prompt", "raw-prompt"],
  ["messages", "messages"],
  ["body", "body"],
  ["authorization", "authorization"],
  ["apikey", "api-key"],
  ["headers", "headers"]
]);

const SECRET_PATTERNS = [
  { name: "secret-key", regex: /(?:^|[^A-Za-z0-9])sk-[A-Za-z0-9_-]{8,}/i },
  { name: "postman-token", regex: /(?:^|[^A-Za-z0-9])phc_[A-Za-z0-9_-]{8,}/i },
  { name: "github-token", regex: /(?:^|[^A-Za-z0-9])ghp_[A-Za-z0-9]{16,}/i },
  { name: "aws-access-key", regex: /(?:^|[^A-Za-z0-9])AKIA[A-Z0-9]{16}(?:$|[^A-Z0-9])/ },
  { name: "private-key", regex: /-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----/ },
  { name: "bearer-token", regex: /(?:^|\s)bearer\s+[A-Za-z0-9._~+\/-]{8,}/i },
  { name: "assigned-secret", regex: /(?:api[_-]?key|access[_-]?token|client[_-]?secret|authorization)\s*[:=]\s*["']?[^\s"',}]{8,}/i }
];

function normalizedKey(key) {
  return String(key).toLowerCase().replace(/[^a-z0-9]/g, "");
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function findUnsafeContent(value, path = "$", depth = 0, findings = []) {
  if (depth > MAX_DEPTH + 4) {
    findings.push({ reason: "structure-too-deep", path });
    return findings;
  }
  if (Array.isArray(value)) {
    value.forEach((item, index) => findUnsafeContent(item, `${path}[${index}]`, depth + 1, findings));
    return findings;
  }
  if (!isPlainObject(value)) return findings;
  for (const [key, child] of Object.entries(value)) {
    const childPath = `${path}.${key}`;
    const forbidden = FORBIDDEN_KEYS.get(normalizedKey(key));
    if (forbidden) findings.push({ reason: forbidden, path: childPath });
    if (typeof child === "string") {
      for (const pattern of SECRET_PATTERNS) {
        if (pattern.regex.test(child)) findings.push({ reason: pattern.name, path: childPath });
      }
    }
    findUnsafeContent(child, childPath, depth + 1, findings);
  }
  return findings;
}

/**
 * Returns findings without retaining the offending value. Callers must not persist
 * the input trace when this function returns a non-empty array.
 */
export function scanTraceForSensitiveContent(trace) {
  if (!isPlainObject(trace)) {
    return [{ reason: "invalid-trace", path: "$" }];
  }
  const findings = [];
  findUnsafeContent(trace, "$", 0, findings);
  const unique = new Map();
  for (const finding of findings) unique.set(`${finding.reason}:${finding.path}`, finding);
  return [...unique.values()];
}

export function isTraceRedacted(trace) {
  return scanTraceForSensitiveContent(trace).length === 0;
}

function validateBoundedValue(value, path = "reproducer", depth = 0) {
  if (depth > MAX_DEPTH) throw new Error(`${path} exceeds the maximum depth of ${MAX_DEPTH}`);
  if (typeof value === "string") {
    if (value.length > MAX_STRING_LENGTH) throw new Error(`${path} exceeds the maximum string length of ${MAX_STRING_LENGTH}`);
    return;
  }
  if (typeof value === "number") {
    if (!Number.isFinite(value)) throw new Error(`${path} must contain only finite numbers`);
    return;
  }
  if (typeof value === "boolean" || value === null) return;
  if (Array.isArray(value)) {
    if (value.length > MAX_ARRAY_ITEMS) throw new Error(`${path} exceeds the maximum array length of ${MAX_ARRAY_ITEMS}`);
    value.forEach((item, index) => validateBoundedValue(item, `${path}[${index}]`, depth + 1));
    return;
  }
  if (!isPlainObject(value)) throw new Error(`${path} contains an unsupported value`);
  const keys = Object.keys(value);
  if (keys.length > MAX_OBJECT_KEYS) throw new Error(`${path} exceeds the maximum object size of ${MAX_OBJECT_KEYS}`);
  for (const [key, child] of Object.entries(value)) {
    const normalized = normalizedKey(key);
    if (normalized === "shell" || normalized === "shellcommand" || normalized === "command") {
      throw new Error(`${path}.${key} is not allowed; reproducer kind command-id accepts an identifier, not a shell command`);
    }
    validateBoundedValue(child, `${path}.${key}`, depth + 1);
  }
}

function canonicalize(value) {
  if (Array.isArray(value)) return value.map(canonicalize);
  if (isPlainObject(value)) {
    return Object.fromEntries(Object.keys(value).sort().map((key) => [key, canonicalize(value[key])]));
  }
  return value;
}

function stableJson(value) {
  return JSON.stringify(canonicalize(value));
}

function digestOf(value) {
  return createHash("sha256").update(stableJson(value), "utf8").digest("hex");
}

function statusOf(trace) {
  const raw = trace.status ?? trace.outcome ?? trace.result?.status ?? trace.result?.outcome;
  return String(raw ?? "").trim().toLowerCase();
}

function attemptOf(trace) {
  const raw = trace.attempt ?? trace.attemptNumber ?? trace.selector?.attempt;
  const attempt = Number(raw);
  if (!Number.isInteger(attempt) || attempt < 0) throw new Error("attempt must be a non-negative integer");
  return attempt;
}

function runIdOf(trace) {
  const raw = trace.runId ?? trace.selector?.runId;
  if (typeof raw !== "string" || raw.trim() === "") throw new Error("runId must be a non-empty string");
  return raw.trim();
}

function traceIdOf(trace) {
  const raw = trace.traceId ?? trace.id ?? trace.result?.traceId;
  if (raw === undefined || raw === null || String(raw).trim() === "") return `${runIdOf(trace)}:${attemptOf(trace)}`;
  return String(raw);
}

function reproducerOf(trace) {
  const raw = trace.reproducer;
  if (!isPlainObject(raw)) throw new Error("reproducer must be an object");
  if (!REPRODUCER_KINDS.has(raw.kind)) throw new Error("reproducer.kind must be scenario, route, or command-id");
  const payload = raw.payload ?? raw.value ?? raw.target;
  if (payload === undefined) throw new Error("reproducer.payload is required");
  validateBoundedValue(payload);
  const serialized = stableJson(payload);
  if (Buffer.byteLength(serialized, "utf8") > MAX_REPRODUCER_BYTES) {
    throw new Error(`reproducer.payload exceeds ${MAX_REPRODUCER_BYTES} bytes`);
  }
  return { kind: raw.kind, payload };
}

function expectationsFor(trace, status) {
  if (FAILURE_STATUSES.has(status)) {
    return { beforeFix: "fail", afterFix: "pass" };
  }
  if (PASS_STATUSES.has(status)) {
    return { beforeFix: "pass", afterFix: "pass" };
  }
  throw new Error(`unsupported trace status: ${status || "missing"}`);
}

/**
 * Converts one already-selected trace into a replayable evaluation sample.
 * This function is pure: it neither reads nor writes files and never starts a
 * process. Sensitive or invalid traces throw and must be handled by the
 * batch wrapper as an individual diagnostic.
 */
export function convertTraceToEvalSample(trace) {
  const findings = scanTraceForSensitiveContent(trace);
  if (findings.length > 0) {
    const error = new Error("trace rejected because it may contain unredacted sensitive content");
    error.code = "TRACE_NOT_REDACTED";
    error.findings = findings.map(({ reason, path }) => ({ reason, path }));
    throw error;
  }
  const status = statusOf(trace);
  const runId = runIdOf(trace);
  const attempt = attemptOf(trace);
  const traceId = traceIdOf(trace);
  const reproducer = reproducerOf(trace);
  const selector = { runId, attempt };
  const expectations = expectationsFor(trace, status);
  const replay = { traceId, reproducer, selector, expectations };
  const digest = digestOf(replay);
  return {
    schemaVersion: 1,
    id: `trace-eval-${digest.slice(0, 20)}`,
    kind: "replay-eval",
    traceId,
    reproducer,
    selector,
    expectations,
    digest: { algorithm: "sha256", value: digest }
  };
}

function isWithinRecentWindow(trace, now) {
  const raw = trace.timestamp ?? trace.createdAt ?? trace.startedAt;
  if (raw === undefined) return true;
  const timestamp = typeof raw === "number" ? raw : Date.parse(String(raw));
  if (!Number.isFinite(timestamp)) return false;
  const age = now - timestamp;
  return age >= 0 && age <= RECENT_TRACE_WINDOW_MS;
}

/**
 * Explicitly converts only traces whose runId occurs in selectedRunIds.
 * No background work is scheduled. Each rejected trace receives a sanitized
 * diagnostic; rejected trace content is never copied into the result.
 */
export function convertSelectedTracesToEvalSamples({ traces, selectedRunIds, now = Date.now(), enforceRecentWindow = false } = {}) {
  if (!Array.isArray(traces)) throw new TypeError("traces must be an array");
  if (!Array.isArray(selectedRunIds)) throw new TypeError("selectedRunIds must be an array");
  const selected = new Set(selectedRunIds.map(String));
  if (selected.size === 0) throw new Error("selectedRunIds must explicitly select at least one runId");
  const samples = [];
  const diagnostics = [];
  for (const trace of traces) {
    let runId;
    try {
      runId = runIdOf(trace);
    } catch {
      diagnostics.push({ code: "INVALID_TRACE", runId: null, reason: "missing-or-invalid-run-id" });
      continue;
    }
    if (!selected.has(runId)) continue;
    if (enforceRecentWindow && !isWithinRecentWindow(trace, Number(now))) {
      diagnostics.push({ code: "OUTSIDE_RECENT_WINDOW", runId, reason: "trace is older than 7 days or has an invalid timestamp" });
      continue;
    }
    try {
      samples.push(convertTraceToEvalSample(trace));
    } catch (error) {
      diagnostics.push({
        code: error?.code === "TRACE_NOT_REDACTED" ? "TRACE_NOT_REDACTED" : "INVALID_TRACE",
        runId,
        reason: error?.code === "TRACE_NOT_REDACTED" ? "trace contains unredacted sensitive content" : "trace does not satisfy the conversion contract",
        findings: error?.code === "TRACE_NOT_REDACTED" ? error.findings : undefined
      });
    }
  }
  return { samples, diagnostics };
}

export const TRACE_TO_EVAL_SAMPLE_LIMITS = Object.freeze({
  maxReproducerBytes: MAX_REPRODUCER_BYTES,
  maxStringLength: MAX_STRING_LENGTH,
  maxDepth: MAX_DEPTH,
  maxArrayItems: MAX_ARRAY_ITEMS,
  maxObjectKeys: MAX_OBJECT_KEYS,
  recentWindowDays: 7
});

export default convertTraceToEvalSample;

export type TraceReproducerKind = "scenario" | "route" | "command-id";

export type TraceStatus =
  | "fail"
  | "failed"
  | "failure"
  | "error"
  | "errored"
  | "pass"
  | "passed"
  | "success"
  | "succeeded"
  | "rejected"
  | "cancelled"
  | "canceled"
  | "skipped";

export interface TraceSelector {
  runId: string;
  attempt: number;
}

export interface TraceReproducer {
  kind: TraceReproducerKind;
  payload: unknown;
}

export interface TraceInput {
  id?: string;
  traceId?: string;
  runId?: string;
  attempt?: number;
  attemptNumber?: number;
  status?: TraceStatus | string;
  outcome?: TraceStatus | string;
  timestamp?: string | number;
  createdAt?: string | number;
  startedAt?: string | number;
  selector?: Partial<TraceSelector>;
  result?: {
    traceId?: string;
    status?: TraceStatus | string;
    outcome?: TraceStatus | string;
  };
  reproducer?: {
    kind?: TraceReproducerKind;
    payload?: unknown;
    value?: unknown;
    target?: unknown;
  };
  [key: string]: unknown;
}

export interface SensitiveContentFinding {
  reason: string;
  path: string;
}

export interface EvalExpectations {
  beforeFix: "fail" | "pass";
  afterFix: "pass";
}

export interface EvalSample {
  schemaVersion: 1;
  id: string;
  kind: "replay-eval";
  traceId: string;
  reproducer: TraceReproducer;
  selector: TraceSelector;
  expectations: EvalExpectations;
  digest: {
    algorithm: "sha256";
    value: string;
  };
}

export interface ConversionDiagnostic {
  code: "TRACE_NOT_REDACTED" | "INVALID_TRACE" | "OUTSIDE_RECENT_WINDOW";
  runId: string | null;
  reason: string;
  findings?: SensitiveContentFinding[];
}

export interface ConvertSelectedOptions {
  traces: TraceInput[];
  selectedRunIds: string[];
  now?: number;
  enforceRecentWindow?: boolean;
}

exexport interface ConversionBatchResult {
  samples: EvalSample[];
  diagnostics: ConversionDiagnostic[];
}

export interface TraceToEvalLimits {
  readonly maxReproducerBytes: number;
  readonly maxStringLength: number;
  readonly maxDepth: number;
  readonly maxArrayItems: number;
  readonly maxObjectKeys: number;
  readonly recentWindowDays: 7;
}

export function scanTraceForSensitiveContent(trace: TraceInput): SensitiveContentFinding[];
export function isTraceRedacted(trace: TraceInput): boolean;
export function convertTraceToEvalSample(trace: TraceInput): EvalSample;
export function convertSelectedTracesToEvalSamples(options: ConvertSelectedOptions): ConversionBatchResult;
export const TRACE_TO_EVAL_SAMPLE_LIMITS: TraceToEvalLimits;
export default convertTraceToEvalSample;

# G03 — Explicit trace-to-evaluation sample converter

## Goal

Convert an explicitly selected, successfully redacted failure trace into a bounded, replayable evaluation sample. A failure sample expects `before-fix=fail` and `after-fix=pass`. A successful, rejected, or cancelled trace expects `pass` both before and after the fix so that a repair cannot regress an existing outcome.

This capability is a library-level, caller-triggered operation. It does not create a timer, automation, daemon, queue, background worker, or recurring scan.

## Contract

`scripts/lib/trace-to-eval-sample.mjs` exports:

- `convertTraceToEvalSample(trace)` for one trace;
- `convertSelectedTracesToEvalSamples({ traces, selectedRunIds, now?, enforceRecentWindow? })` for an explicit batch;
- `scanTraceForSensitiveContent(trace)` and `isTraceRedacted(trace)` for preflight checks;
- `TRACE_TO_EVAL_SAMPLE_LIMITS` for the documented bounds.

The converter is pure. It does not read evidence, write samples, delete evidence, spawn a process, access the network, or alter product defaults, locks, approvals, or permissions. Persistence and selection remain the caller's responsibility.

## Trace input

A trace must provide:

- `runId` (or `selector.runId`);
- a non-negative integer `attempt` (or `selector.attempt`);
- a status/outcome;
- a reproducer with `kind` equal to `scenario`, `route`, or `command-id`;
- a bounded reproducer payload.

There is no shell reproducer kind. A `command-id` payload may identify a command but may not contain a shell command. Payload size is limited to 16 KiB, nesting to four levels, strings to 4096 characters, arrays to 100 entries, and objects to 50 keys.

## Explicit selection

`selectedRunIds` is mandatory and must not be empty. Traces outside that selection are ignored. No trace is selected implicitly. `enforceRecentWindow` may be used by a caller to constrain selection to the preceding seven days; timestamps are evaluated only for selected traces. Selection never invokes an automation or starts recurring work.

## Redaction and refusal

The complete selected trace is scanned before conversion. A trace is refused in its entirety when a forbidden field is present, including `rawPrompt`, `prompt`, `messages`, `body`, `authorization`, `apiKey`, or `headers` (field-name comparison is case-insensitive and ignores punctuation), or when content resembles:

- a secret key (`sk-...`);
- a Postman token (`phc_...`);
- a GitHub personal token (`ghp_...`);
- an AWS access key (`AKIA...`);
- a PEM private key;
- a bearer token;
- an assigned API key, access token, client secret, or authorization value.

A refusal produces only a sanitized diagnostic containing the reason and field path. The offending value and source trace are never copied into a sample. Original evidence is neither modified nor deleted.

## Sample shape

A sample contains:

- `schemaVersion: 1` and `kind: replay-eval`;
- `traceId`;
- the bounded `reproducer`;
- `selector: { runId, attempt }`;
- `expectations: { beforeFix, afterFix }`;
- a deterministic SHA-256 `digest` and its algorithm.

The digest is calculated over canonical JSON containing the trace ID, reproducer, selector, and expectations. The same inputs therefore produce the same sample ID and digest for replay comparison.

## Batch behavior

Every selected trace is handled independently. Valid traces produce samples. Invalid or unredacted traces produce one diagnostic each. A single refusal does not abort the rest of the explicit batch. Diagnostics must not contain raw values.

## Verification

1. Convert one redacted failure and assert `beforeFix=fail`, `afterFix=pass`, bounded reproducer/selector, and a repeatable SHA-256 digest.
2. Convert success, rejection, and cancellation traces and assert both expectations are `pass`.
3. Assert traces containing every forbidden field and representative secret patterns are rejected and produce no sample.
4. Assert batch conversion selects only explicitly named run IDs and emits one sanitized diagnostic per rejected selected trace.
5. Assert no timer, scheduler, daemon, network call, process spawn, or source-evidence mutation exists.
6. Run the targeted tests, type check, scoped lint, harness validation/dry-run, credential scan, and verify `SHA256SUMS` can be read back.

